window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"nRMcr-jPnRw","speaker":"Daniel Roy-Gilchrist Noboa Azin","role":"Constitutional President","country":"Ecuador","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=nRMcr-jPnRw","date":"20260923","title":"🇪🇨 Ecuador - Constitutional President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":509,"words":1255,"counts":{"claims":14,"promises":2,"attacks":0},"topics":[{"topic":"Ecuador security","share":0.2682,"seconds":136},{"topic":"Organized crime","share":0.2007,"seconds":102},{"topic":"AI governance","share":0.1397,"seconds":71},{"topic":"UN reform","share":0.1339,"seconds":68},{"topic":"Illegal fishing","share":0.1329,"seconds":68},{"topic":"Transnational crime","share":0.1247,"seconds":63}],"timeline":[[6,102,null],[103,166,"Ecuador security"],[167,229,"Organized crime"],[230,293,"Transnational crime"],[294,367,"Ecuador security"],[368,435,"Illegal fishing"],[436,507,"AI governance"],[509,577,"UN reform"],[578,618,"Organized crime"]],"stances":{"Ecuador security":"Daniel Roy-Gilchrist Noboa Azin states that Ecuador has moved from a state where fear prevailed to one of determination, but emphasizes that the country cannot defeat borderless criminal enemies acting alone.","Organized crime":"Daniel Roy-Gilchrist Noboa Azin argues that organized crime has evolved into a transnational threat to international peace and security that requires action from actors beyond just states.","Transnational crime":"Daniel Roy-Gilchrist Noboa Azin proposes three concrete UN actions to combat transnational organized crime by tracing illicit financial flows, establishing an information exchange platform, and prioritizing conflict prevention.","Illegal fishing":"Daniel Roy-Gilchrist Noboa Azin states that illegal fishing networks threaten the Galapagos Islands and operate with the same logic as other organized crime groups.","AI governance":"Daniel Roy-Gilchrist Noboa Azin argues that international governance is needed for artificial intelligence to ensure innovation without sacrificing values and to prevent leaving those with fewer resources behind.","UN reform":"Daniel Roy-Gilchrist Noboa Azin advocates for transforming the United Nations to be more efficient, conflict-preventive, and legitimate through adherence to international law."},"claims":[{"t":121,"quote":"there was a time in which in my country fear prevailed over the law. This was the experience of families that when going out at night, business owners who had to pay to be able to work, young people who were given weapons before they were given a","topic":"Ecuador security","kind":"fact"},{"t":157,"quote":"The weapons that reach our streets cross several countries. The money that finances mafias is laundered far from where the crimes are committed.","topic":"Ecuador security","kind":"fact"},{"t":173,"quote":"Criminals have already globalized their cooperation. They share routes, logistics, finances, and technology without red tape, distrust, or delay.","topic":"Organized crime","kind":"fact"},{"t":185,"quote":"It's unacceptable that criminal organizations cooperate among with with one another more effectively than states do.","topic":"Organized crime","kind":"fact"},{"t":242,"quote":"First of all, an international mechanism within the framework of the UN to trace and freeze the illicit financial flows from transnational organized crime.","topic":"Transnational crime","kind":"fact"},{"t":253,"quote":"The money is the fuel of these networks, so let us stop it in its tracks.","topic":"Transnational crime","kind":"fact"},{"t":308,"quote":"For a young person to be able to choose university rather than being trapped by a criminal gang.","topic":"Ecuador security","kind":"fact"},{"t":325,"quote":"The success of an economy is not measured only by how much production grows, but rather how much it's able to reduce poverty.","topic":"Ecuador security","kind":"fact"},{"t":389,"quote":"The Galapagos Islands, where Darwin uh found evidence of the evolution of life, are a world heritage site for the whole of humanity.","topic":"Illegal fishing","kind":"fact"},{"t":397,"quote":"And today, they are threatened by illegal fishing networks that operate with the same logic and the same financing of other organized crime groups.","topic":"Illegal fishing","kind":"fact"},{"t":450,"quote":"It can transform education, multiply productivity, and close historic gaps, but um also entrench inequalities and serve those that seek to weaken our institutions.","topic":"AI governance","kind":"fact"},{"t":477,"quote":"Many citizens see a gulf between what we agree on here and what people experience on a daily basis.","topic":"AI governance","kind":"fact"},{"t":547,"quote":"More than 80 years ago, countries understood that didn't depend on, um, everyone's power, but rather, um, is something that, um, we built organizations to cooperate to achieve.","topic":"UN reform","kind":"fact"},{"t":579,"quote":"the criminal gangs already coordinate with each other","topic":"Organized crime","kind":"fact"}],"promises":[{"t":286,"quote":"These are proposals that Ecuador is prepared to support and drive forward alongside all countries that wish to join us.","topic":"Transnational crime","kind":"promise"},{"t":416,"quote":"Ecuador will uh continue to fulfill our responsibilities","topic":"Illegal fishing","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":6,"topic":null,"text":"The assembly will now hear an address by his Excellency Mr. Daniel Roy Gilchrist Noboa Azin, constitutional president of the Republic of Ecuador. I request protocol to please escort his Excellency and invite him to address the Secretary"},{"t":103,"topic":"Ecuador security","text":"General of the United Nations Mr. President of the General Assembly Excellencies, heads of state and distinguished delegations ladies and gentlemen. there was a time in which in my country fear prevailed over the law. This was the experience of families that when going out at night, business owners who had to pay to be able to work, young people who were given weapons before they were given a We decided that this should not be the destiny of Ecuador and we have acted with determination. However, on this journey we have learned something that I have come here to share with you. That is that no state can defeat an enemy that knows no borders by acting alone. The weapons that reach our streets cross several countries. The money that finances mafias is laundered far from where the crimes are committed."},{"t":167,"topic":"Organized crime","text":"The roots of drug trafficking and people trafficking and illegal mining cross continents. Criminals have already globalized their cooperation. They share routes, logistics, finances, and technology without red tape, distrust, or delay. It's unacceptable that criminal organizations cooperate among with with one another more effectively than states do. This is the reality that the United Nations must recognize and rise to. For a long time organized crime was dealt with as a law enforcement matter, but today we know that it's more than that. When it controls territories and infiltrates institutions, replaces legitimate authority, erodes the rule of law, and destabilizes an entire society. And when this happens in several countries at the same time, it's no longer just a domestic issue. It becomes a threat to international peace and security. I want to say this very clearly, we're calling for other actors to act instead of states."},{"t":230,"topic":"Transnational crime","text":"We're calling for cooperation with full respect for the sovereignty of each nation and with results that we can This is why Ecuador today is proposing three concrete actions. First of all, an international mechanism within the framework of the UN to trace and freeze the illicit financial flows from transnational organized crime. The money is the fuel of these networks, so let us stop it in its tracks. permanent platform of information exchange between police forces, prosecutor's offices, and financial intelligence units that enable states to anticipate rather than react once it's happened. And the third concrete action that the UN 80 initiative include transnational organized crime as a priority for conflict prevention and provide the organization with the capacity to support states that request it. These are proposals that Ecuador is prepared to support and drive forward alongside all countries that wish to join us."},{"t":294,"topic":"Ecuador security","text":"Excellencies, security is not an end into itself. It's a condition for a country to be able to flourish, and today we are experiencing a crisis. A profound crisis, and recovering security means giving people back their future. For a young person to be able to choose university rather than being trapped by a criminal gang. For a family to open a business without fear. For a company to invest and create jobs. And for institutions to respond to the needs of citizens and not to illicit interests. Therefore, the success of an economy is not measured only by how much production grows, but rather how much it's able to reduce poverty. It's measured in um young people with decent jobs and children with a better education in citizens who are able to build their future with a dignity. And this also must guide the agenda of international development. Middle-income countries face vulnerabilities that income per capita does not reflect. We ask that access to cooperation and financing be defined using more fair vulnerability criteria and that the international financial architecture support the efforts of those who are undertaking reforms."},{"t":368,"topic":"Illegal fishing","text":"We believe in open, predictable, and equitable trade when a producer can export, innovate, and grow. There's a family behind that um can be lifted out of poverty. The best social policy is policy that generates President, I come from a country that is small in size but great, huge in terms of our nature. The Galapagos Islands, where Darwin uh found evidence of the evolution of life, are a world heritage site for the whole of humanity. And today, they are threatened by illegal fishing networks that operate with the same logic and the same financing of other organized crime groups. And the same is happening with illegal mining in the Amazon that's destroying forests and funding gangs. Protecting nature is also a matter of security. Ecuador will uh continue to fulfill our responsibilities and invites all of you to join to join Latin America and the Caribbean is a region with a lot of talent talent, energy, food, strategic resources, and above all uh youth that is resolved to building a different future."},{"t":436,"topic":"AI governance","text":"It's a region that um has not come to this assembly to ask for uh solutions from the outside, but rather to offer up our solutions and one with the greatest um one of the greatest challenges of the future is artificial intelligence. It can transform education, multiply productivity, and close historic gaps, but um also entrench inequalities and serve those that seek to weaken our institutions. We need international governance that enables us to innovate without renouncing our values and that does not leave those that have the least resources behind. Um, they also need to be able to access this technology. Excellencies, um, confidence in the multilateral system is going through difficult times. Many citizens see a gulf between what we agree on here and what people experience on a daily basis. Closing this gap is the task of our organization. A lot of, um, citizens realize that, um, this is the task that our generation must take up and as a founding country, Ecuador believes in the United Nations and it's it's precisely for this reason that we want an organization that's able to respond to the challenges of the world today, not of 1945."},{"t":509,"topic":"UN reform","text":"Supporting the organization that the, you know, United Nations also needs to involve, um, a willingness to transform the United Nations and that's why we support the UN 80 initiative and, um, pose an essential question. What United Nations does the world needs today? Um, we need an organization that's more efficient with the ability to prevent conflicts, resolve crises and support states to challenges that didn't exist when the organization was created. An organization whose legitimacy depends not only on the decision that we adopt, but the way that they adopt and we need the charter and international law to remain our common language. More than 80 years ago, countries understood that didn't depend on, um, everyone's power, but rather, um, is something that, um, we built organizations to cooperate to achieve. This remains our main strength. The citizens of the world will not judge this organization by its declarations, they will judge it by its ability to turn commitments into peace and security, into respect for human rights, into real opportunities for development and how many lives we really save."},{"t":578,"topic":"Organized crime","text":"President, the criminal gangs already coordinate with each other. Now, we need to do better. has come to this assembly to defend collective solutions because no country can build a safe, prosperous, and sustainable future alone. And because when international cooperation works, we are all stronger for it. Thank you very much. On behalf of the assembly, I wish to thank the constitutional president of the Republic of Ecuador. &gt;&gt; Okay, here we go."}],"compare":[{"topic":"Ecuador","share":0.2682,"mean":0.0,"rank":1,"others":0},{"topic":"Transnational Crime","share":0.2007,"mean":0.0026,"rank":2,"others":4},{"topic":"Artificial Intelligence","share":0.1397,"mean":0.05,"rank":22,"others":83},{"topic":"UN & its reform","share":0.1339,"mean":0.2051,"rank":126,"others":170},{"topic":"Maritime Security","share":0.1329,"mean":0.004,"rank":3,"others":9},{"topic":"Transnational crime","share":0.1247,"mean":0.0024,"rank":2,"others":4}]};
